1	import { useEffect, useRef, useState } from 'react';
2	
3	import { Button } from '@app/components/ui/button';
4	import { Tooltip, TooltipContent, TooltipTrigger } from '@app/components/ui/tooltip';
5	import { cn } from '@app/lib/utils';
6	import { ChevronLeft, ChevronRight } from 'lucide-react';
7	
8	interface PageWrapperProps {
9	  title: string;
10	  description?: React.ReactNode;
11	  children: React.ReactNode;
12	  onNext?: () => void;
13	  onBack?: () => void;
14	  nextLabel?: string;
15	  backLabel?: string;
16	  nextDisabled?: boolean;
17	  backDisabled?: boolean;
18	  warningMessage?: string;
19	}
20	
21	export default function PageWrapper({
22	  title,
23	  description,
24	  children,
25	  onNext,
26	  onBack,
27	  nextLabel = 'Next',
28	  backLabel = 'Back',
29	  nextDisabled = false,
30	  backDisabled = false,
31	  warningMessage,
32	}: PageWrapperProps) {
33	  const [isMinimized, setIsMinimized] = useState(false);
34	  const contentRef = useRef<HTMLDivElement>(null);
35	  const lastToggleTimeRef = useRef<number>(0);
36	
37	  // Scroll behavior configuration
38	  // Minimize when user has scrolled down a bit; expand only when at the very top
39	  const MINIMIZE_SCROLLTOP = 24;
40	  const EXPAND_AT_TOP_SCROLLTOP = 1; // treat 0–1px as top
41	  const TOGGLE_COOLDOWN_MS = 250; // brief cooldown to absorb layout changes and transitions
42	
43	  useEffect(() => {
44	    const contentElement = contentRef.current;
45	    if (!contentElement) {
46	      return;
47	    }
48	
49	    const applyStateFromMetrics = () => {
50	      const scrollTop = contentElement.scrollTop;
51	      const now = performance.now();
52	
53	      // Cooldown to avoid immediate re-toggling due to layout shift
54	      if (now - lastToggleTimeRef.current < TOGGLE_COOLDOWN_MS) {
55	        return;
56	      }
57	
58	      setIsMinimized((prev) => {
59	        // Expand only at top
60	        if (scrollTop <= EXPAND_AT_TOP_SCROLLTOP) {
61	          if (prev) {
62	            lastToggleTimeRef.current = now;
63	          }
64	          return false;
65	        }
66	        // Minimize when user has scrolled away from top a bit
67	        if (!prev && scrollTop >= MINIMIZE_SCROLLTOP) {
68	          lastToggleTimeRef.current = now;
69	          return true;
70	        }
71	        return prev;
72	      });
73	    };
74	
75	    // Initial evaluation in case the container is already scrolled
76	    applyStateFromMetrics();
77	
78	    const onScroll = () => applyStateFromMetrics();
79	    const onResize = () => applyStateFromMetrics();
80	
81	    contentElement.addEventListener('scroll', onScroll, { passive: true });
82	    window.addEventListener('resize', onResize);
83	    return () => {
84	      contentElement.removeEventListener('scroll', onScroll);
85	      window.removeEventListener('resize', onResize);
86	    };
87	  }, []);
88	
89	  const nextButton = (
90	    <Button onClick={onNext} disabled={nextDisabled} className="mr-[72px] px-6 py-2">
91	      {nextLabel}
92	      <ChevronRight className="ml-1 size-4" />
93	    </Button>
94	  );
95	
96	  return (
97	    <div className="flex h-screen w-full flex-col overflow-hidden">
98	      {/* Header */}
99	      <div
100	        className={cn(
101	          'sticky top-0 z-10 border-b border-border backdrop-blur-sm',
102	          'bg-background/90 dark:bg-background/90',
103	          'transition-[padding] duration-200 ease-in-out',
104	          isMinimized ? 'px-6 py-3' : 'p-6',
105	        )}
106	      >
107	        <h1
108	          className={cn(
109	            'font-semibold text-foreground transition-[font-size] duration-200 ease-in-out',
110	            isMinimized ? 'mb-0 text-xl' : 'mb-2 text-3xl',
111	          )}
112	        >
113	          {title}
114	        </h1>
115	        {description && (
116	          <div
117	            className={cn(
118	              'overflow-hidden text-base text-muted-foreground transition-all duration-200 ease-in-out',
119	              'max-h-[320px] md:max-h-[100px]',
120	              isMinimized ? 'max-h-0 opacity-0 md:max-h-0' : 'opacity-100',
121	            )}
122	          >
123	            {description}
124	          </div>
125	        )}
126	      </div>
127	
128	      {/* Content */}
129	      <div ref={contentRef} className="relative h-0 flex-1 overflow-auto">
130	        <div className="p-6 pb-48">{children}</div>
131	      </div>
132	
133	      {/* Navigation */}
134	      {(onBack || onNext) && (
135	        <div
136	          data-testid="page-navigation"
137	          className="fixed bottom-0 left-0 right-0 z-[15] flex items-center justify-between border-t border-border bg-card/95 px-6 py-4 backdrop-blur-sm md:left-[var(--sidebar-width)]"
138	          style={{ '--sidebar-width': '240px' } as React.CSSProperties}
139	        >
140	          <div>
141	            {onBack && (
142	              <Button variant="outline" onClick={onBack} disabled={backDisabled} className="px-6">
143	                <ChevronLeft className="mr-1 size-4" />
144	                {backLabel}
145	              </Button>
146	            )}
147	          </div>
148	          <div>
149	            {onNext &&
150	              (warningMessage ? (
151	                <Tooltip>
152	                  <TooltipTrigger asChild>
153	                    <span
154	                      className={cn(
155	                        'inline-block',
156	                        nextDisabled ? 'cursor-not-allowed' : 'cursor-pointer',
157	                      )}
158	                    >
159	                      {nextButton}
160	                    </span>
161	                  </TooltipTrigger>
162	                  <TooltipContent side="top">{warningMessage}</TooltipContent>
163	                </Tooltip>
164	              ) : (
165	                nextButton
166	              ))}
167	          </div>
168	        </div>
169	      )}
170	    </div>
171	  );
172	}
